// 1. 斷言 Status Code 是否為 201 Created
pm.test("Status code is 201 Created", function () {
    pm.response.to.have.status(201);
});

// 2. 解析 JSON 回應並寫入環境變數
const responseData = pm.response.json();

pm.test("Response contains generated ID", function () {
    pm.expect(responseData).to.have.property('id');
    
    // 將產生的 ID 寫入環境變數作為 Token/Session 代表
    pm.environment.set("token", "simulated_token_" + responseData.id);
    pm.environment.set("userId", responseData.userId);
});

// 1. 斷言 Status Code 200
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const schema = {
    "type": "array",
    "items": {
        "type": "object",
        "required": ["userId", "id", "title", "body"],
        "properties": {
            "userId": { "type": "number" },
            "id": { "type": "number" },
            "title": { "type": "string" },
            "body": { "type": "string" }
        }
    }
};

// 💡 執行 Schema 結構驗證
pm.test("Response Schema is valid", function () {
    pm.response.to.have.jsonSchema(schema);
});

// 2. 解析 JSON 並自動抓取第一篇文章的 ID
const responseData = pm.response.json();

pm.test("Posts array is not empty and store first postId", function () {
    pm.expect(responseData).to.be.an('array').that.is.not.empty;

    // 取得第一筆文章的 ID 並存入環境變數
    const firstPostId = responseData[0].id;
    pm.environment.set("postId", firstPostId);
});

pm.test("Status code is 201 Created", function () {
    pm.response.to.have.status(201);
});

const responseData = pm.response.json();

// 把伺服器回傳的留言內文 (body) 印在左下角的 Console 視窗中
console.log("剛剛發布的留言內容為：", responseData.body);
console.log("這筆留言的專屬 ID 為：", responseData.id);

pm.test("Verify comment is linked to correct postId", function () {
    pm.expect(responseData.postId).to.eql(pm.environment.get("postId"));
});

pm.test("Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

// 自動清理測試過程中產生的環境變數（保持環境乾淨）
pm.test("Cleanup temporary environment variables", function () {
    pm.environment.unset("postId");
});
